public class SignupErrorCollectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object problems(String name, int age, String email) {
        try {
            java.util.List<String> found = SignupErrorCollector.validate(name, age, email);
            return found == null ? "<null>" : found.toString();
        } catch (Throwable crash) {
            return "validate threw " + crash.getClass().getSimpleName();
        }
    }

    static Object thrownMessage(String name, int age, String email) {
        try {
            SignupErrorCollector.validateOrThrow(name, age, email);
            return "<no exception>";
        } catch (IllegalArgumentException rejected) {
            return rejected.getMessage();
        } catch (Throwable crash) {
            return "threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("a good signup has no problems", "[]", problems("Ada", 36, "ada@example.com"));
        check("blank name only", "[name is blank]", problems("   ", 36, "ada@example.com"));
        check("young age only", "[age out of range]", problems("Ada", 12, "ada@example.com"));
        check("bad email only", "[email missing @]", problems("Ada", 36, "ada.example.com"));
        check("all three problems at once", "[name is blank, age out of range, email missing @]",
                problems(null, 121, null));
        check("age 13 and age 120 are allowed", "[]", problems("Ada", 13, "a@b"));
        check("a good signup throws nothing", "<no exception>",
                thrownMessage("Ada", 36, "ada@example.com"));
        check("the thrown message joins every problem",
                "name is blank; age out of range; email missing @", thrownMessage("", 9, "nope"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
