/**
 * TASK: Report every problem with a signup instead of stopping at the first.
 *
 * validate(name, age, email) returns a List<String> of problem messages. Test
 * all three rules and add a message, in this exact order, for each one broken:
 *   "name is blank"     -- name is null or contains only whitespace
 *   "age out of range"  -- age is below 13 or above 120
 *   "email missing @"   -- email is null or has no '@' in it
 * A perfectly good signup produces an EMPTY list.
 *
 * validateOrThrow(name, age, email) asks validate for the problems. With no
 * problems it simply returns. Otherwise it throws an IllegalArgumentException
 * whose message is every problem joined with "; ".
 *
 * Example: validate("", 9, "nope") -> [name is blank, age out of range, email missing @]
 *          validateOrThrow("", 9, "nope") throws IllegalArgumentException
 *              with the message "name is blank; age out of range; email missing @"
 */
import java.util.ArrayList;
import java.util.List;

public class SignupErrorCollector {

    public static List<String> validate(String name, int age, String email) {
        List<String> problems = new ArrayList<>();
        if (name == null || name.trim().isEmpty()) {
            problems.add("name is blank");
        }
        if (age < 13 || age > 120) {
            problems.add("age out of range");
        }
        if (email == null || email.indexOf('@') < 0) {
            problems.add("email missing @");
        }
        return problems;
    }

    public static void validateOrThrow(String name, int age, String email) {
        List<String> problems = validate(name, age, email);
        if (problems.isEmpty()) {
            return;
        }
        StringBuilder message = new StringBuilder();
        for (String problem : problems) {
            if (message.length() > 0) {
                message.append("; ");
            }
            message.append(problem);
        }
        throw new IllegalArgumentException(message.toString());
    }
}
